import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written double for the downstream pricing service (priceOf(sku) -> euros).
const prices = { A: 10, B: 60, THIRD: 100 / 3, HUNDRED: 100, P101: 101 }
const priceCalls = []
const pricing = { async priceOf(sku) { priceCalls.push(sku); return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const call = async (method, path, body, raw) => {
  const res = await fetch(base + path, { method, body: raw ?? (body === undefined ? undefined : JSON.stringify(body)) })
  return { res, json: await res.json() }
}
const post = (items) => call('POST', '/orders', { items })

// Order state is module-level and ids are sequential, so this test must run first.
test('POST /orders creates an order: 201, string id from 1, items echoed, total computed', async () => {
  const { res, json } = await post([{ sku: 'A', qty: 3 }])
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(json, { id: '1', items: [{ sku: 'A', qty: 3 }], total: 30 })
  assert.deepEqual(priceCalls, ['A'])
  const second = await post([{ sku: 'A', qty: 1 }])
  assert.equal(second.json.id, '2')
})

test('POST /orders sums several lines', async () => {
  const { json } = await post([{ sku: 'A', qty: 1 }, { sku: 'B', qty: 1 }])
  assert.equal(json.total, 70)
})

test('POST /orders: total over 100 gets 10% off', async () => {
  const { json } = await post([{ sku: 'B', qty: 2 }])
  assert.equal(json.total, 108)
})

test('POST /orders: exactly 100 gets no discount; 101 is discounted then floored', async () => {
  assert.equal((await post([{ sku: 'HUNDRED', qty: 1 }])).json.total, 100)
  assert.equal((await post([{ sku: 'P101', qty: 1 }])).json.total, 90) // 90.9 floored
})

test('POST /orders: total is floored to whole euros, not rounded', async () => {
  // CHARACTERIZATION: current behaviour may be unintended - cents are truncated (99.99 -> 99)
  assert.equal((await post([{ sku: 'THIRD', qty: 3 }])).json.total, 99)
})

test('POST /orders: 400 when items missing, empty, not an array, or body is invalid JSON', async () => {
  for (const body of [{}, { items: [] }, { items: 'A' }, { items: {} }, null]) {
    const { res, json } = await call('POST', '/orders', body)
    assert.equal(res.status, 400, JSON.stringify(body))
    assert.deepEqual(json, { error: 'items required' })
    assert.equal(res.headers.get('content-type'), 'application/json')
  }
  const bad = await call('POST', '/orders', undefined, '{not json')
  assert.equal(bad.res.status, 400)
  assert.deepEqual(bad.json, { error: 'items required' })
  // empty body parses as {} -> also 400
  const empty = await call('POST', '/orders')
  assert.equal(empty.res.status, 400)
})

test('GET /orders/:id returns the stored order', async () => {
  const created = (await post([{ sku: 'A', qty: 2 }])).json
  const { res, json } = await call('GET', `/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(json, { id: created.id, items: [{ sku: 'A', qty: 2 }], total: 20 })
})

test('GET /orders/:id for an unknown id answers 200 with an error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended - "not found" is returned with status 200, not 404
  const { res, json } = await call('GET', '/orders/does-not-exist')
  assert.equal(res.status, 200)
  assert.deepEqual(json, { error: 'not found' })
})

test('any other method/path answers 404 {error:"no route"}', async () => {
  for (const [m, p] of [['GET', '/orders'], ['DELETE', '/orders/1'], ['PUT', '/orders/1'], ['POST', '/orders/1'], ['GET', '/'], ['GET', '/orders/1/items'], ['GET', '/health']]) {
    const { res, json } = await call(m, p)
    assert.equal(res.status, 404, `${m} ${p}`)
    assert.deepEqual(json, { error: 'no route' })
    assert.equal(res.headers.get('content-type'), 'application/json')
  }
})
EOF
